cssText:
.stage { background: radial-gradient(120% 80% at 50% 40%, #3E1F86 0%, #2C1660 55%, #20104A 100%); }
.hud-series { font-family: var(--font-mono); text-transform: uppercase; letter-spacing: .2em; font-weight: 600; }
.hud-badge { letter-spacing: .02em; font-family: var(--font-mono); }
.hud-counter .v, .hud-scale, .hud-badge { font-feature-settings: "tnum" 1; }
